const (
	width  = picopad.Width
	height = picopad.Height

	fontW = 8           // font width
	fontH = 16          // font height
	textW = width / 8   // width of the text screen (40)
	textH = height / 16 // height of the text screen (15)

	moveSpeed = 50 // step delay [ms]

	mapWMax = width / 4  // max. width of the game board
	mapHMax = height / 4 // max. height of the game board

	// tiles
	tileEmpty = 0  // empty (grass)
	tileWall  = 1  // wall
	tileFloor = 2  // floor
	tileMark  = 3  // mark
	tileCrate = 4  // crate
	tileFull  = 5  // crate on a mark
	faceR     = 6  // (4) face right
	faceU     = 10 // (4) face up
	faceL     = 14 // (4) face left
	faceD     = 18 // (4) face down
	faceWin   = 22 // winning face
	tilesNum  = 23 // number of tiles

	// directions
	dirR = 0
	dirU = 1
	dirL = 2
	dirD = 3
)

// collect is a collection of levels: a definition and a solution a line
// each.
type collect struct {
	name   string
	levels string
	num    int
}

// level returns the definition and the solution of level i.
func level(levels string, i int) (def, sol string) {
	for n := 2 * i; n > 0; n-- {
		levels = levels[strings.IndexByte(levels, '\n')+1:]
	}
	k := strings.IndexByte(levels, '\n')
	def, levels = levels[:k], levels[k+1:]
	return def, levels[:strings.IndexByte(levels, '\n')]
}

// author is an author with the collections.
type author struct {
	name    string
	collect []collect
}

// authors are the authors of the levels (the ones of PicoLibSDK that let
// them be distributed freely).
var authors = [...]author{
	{"Brian Damgaard", damgaardCol[:]},
	{"David Holland", hollandCol[:]},
	{"David W. Skinner", skinnerCol[:]},
	{"Evgeny Grigoriev", grigorCol[:]},
	{"Jean-Pierre Martel", martelCol[:]},
	{"Lee J. Haywood", haywoodCol[:]},
	{"Rick Sladkey", sladkeyCol[:]},
}

// introLevel is the demo level (19x15: tiles 16x16) of
// src/levels.cpp:
//
//	x = grass (empty), # = wall, ! or | = next row,
//	space or _ or - = floor, $ or b = box, * or B = box on mark,
//	. = mark, @ or p = player, + or P = player on mark
const introLevel = "" +
	"x##xx#xx#x#xx#x!" +
	"#xxx#x#x#x#x#x#!" +
	"x#xx#x#x##xx#x#!" +
	"xx#x#x#x#x#x#x#!" +
	"##xxx#xx#x#xx#!" +
	"!" +
	"xxxxxxx##xxx#xx#xx#!" +
	"xxxxxxx#x#x#x#x##x#!" +
	"xxxxxxx##xx###x####!" +
	"xxxxxxx#x#x#x#x#x##!" +
	"xxxxxxx##xx#x#x#xx#!" +
	"###################!" +
	"#.    $  @  $    .#!" +
	"#. $     *     $ .#!" +
	"###################!\n" +
	"rrRRRRRlldRRullllllllllLLLLLrrdLL\n"

// Game is Sokoban on a console.
type Game struct {
	*picopad.Console

	board      [mapWMax * mapHMax]uint8
	mapW, mapH int // current board dimension
	tileSize   int // current tile size (4, 8 ... 32, 0: text)

	markNum        int  // remaining marks
	levelW, levelH int  // level width and height
	levelX, levelY int  // level coordinates
	posX, posY     int  // player coordinates
	fastMode       bool // fast mode

	tilesImgPal picopad.Palette
	tilesImg    string
	tilesImgW   int

	saveScr            [32 * 32]picopad.Color // the screen under the player
	saveScrOn          bool
	saveScrX, saveScrY int

	// the selected level, collection and author
	level      int
	levDef     string
	levSolve   string
	levNum     int
	levels     string
	collName   string
	collNum    int
	collInx    int
	collect    []collect
	autName    string
	autInx     int
	collTotal  int
	levelTotal int
}

// New returns the game on d (at least 320x240) with the touch panel t;
// seed starts the random numbers (the levels of the demo). Set Pad to use
// a game controller.
func New(d hal.Display, t hal.Touch, seed uint32) *Game {
	return &Game{Console: picopad.New(d, t, seed)}
}

// setTileMode sets the tile size (0: text mode) and clears the screen.
func (g *Game) setTileMode(tilesize int) {
	if tilesize > 0 && tilesize < 4 {
		tilesize = 4
	}
	if tilesize > 32 {
		tilesize = 32
	}
	tilesize &^= 3
	g.tileSize = tilesize

	switch tilesize {
	case 32:
		g.tilesImgPal, g.tilesImg = tiles32ImgPal, tiles32Img
	case 28:
		g.tilesImgPal, g.tilesImg = tiles28ImgPal, tiles28Img
	case 24:
		g.tilesImgPal, g.tilesImg = tiles24ImgPal, tiles24Img
	case 20:
		g.tilesImgPal, g.tilesImg = tiles20ImgPal, tiles20Img
	case 16:
		g.tilesImgPal, g.tilesImg = tiles16ImgPal, tiles16Img
	case 12:
		g.tilesImgPal, g.tilesImg = tiles12ImgPal, tiles12Img
	case 8:
		g.tilesImgPal, g.tilesImg = tiles8ImgPal, tiles8Img
	default:
		g.tilesImgPal, g.tilesImg = tiles4ImgPal, tiles4Img
	}
	g.tilesImgW = tilesize * tilesNum

	if tilesize > 0 {
		g.mapW = width / tilesize
		g.mapH = height / tilesize
	}
	g.DrawClear()
	g.KeyFlush()
}

// dispTile displays one tile of the board.
func (g *Game) dispTile(x, y int) {
	tile := int(g.board[x+y*g.mapW])
	g.DrawImg4Pal(g.tilesImg, g.tilesImgPal, tile*g.tileSize, 0,
		x*g.tileSize+g.levelX, y*g.tileSize+g.levelY, g.tileSize, g.tileSize, g.tilesImgW)
}

// dispBoard displays all the tiles.
func (g *Game) dispBoard() {
	for y := 0; y < g.mapH; y++ {
		for x := 0; x < g.mapW; x++ {
			g.dispTile(x, y)
		}
	}
	g.saveScrOn = false
}

// putTile puts a tile on the board.
func (g *Game) putTile(x, y int, tile uint8) {
	g.board[x+y*g.mapW] = tile
	g.dispTile(x, y)
}

// getTile returns a tile (empty out of the board).
func (g *Game) getTile(x, y int) uint8 {
	if x < 0 || x >= g.mapW || y < 0 || y >= g.mapH {
		return tileEmpty
	}
	return g.board[x+y*g.mapW]
}

// savePlayer saves the screen under the player (C: from FrameBuf).
func (g *Game) savePlayer(x, y int) {
	g.saveScrOn = true
	g.saveScrX, g.saveScrY = x, y
	ts := g.tileSize
	for h := 0; h < ts; h++ {
		for w := 0; w < ts; w++ {
			g.saveScr[h*ts+w] = g.DrawGetPoint(x+w, y+h)
		}
	}
}

// restorePlayer restores the screen under the player.
func (g *Game) restorePlayer() {
	if !g.saveScrOn {
		return
	}
	ts := g.tileSize
	for h := 0; h < ts; h++ {
		for w := 0; w < ts; w++ {
			g.DrawPoint(g.saveScrX+w, g.saveScrY+h, g.saveScr[h*ts+w])
		}
	}
}

// setPlayer draws the player at x, y of the level.
func (g *Game) setPlayer(x, y int, tile uint8) {
	x += g.levelX
	y += g.levelY
	g.restorePlayer()
	g.savePlayer(x, y)
	g.DrawBlit4Pal(g.tilesImg, g.tilesImgPal, int(tile)*g.tileSize, 0, x, y, g.tileSize, g.tileSize,
		g.tilesImgW, picopad.RGB(84, 0, 84)) // TRANSCOL
}

// movePlayer moves the player one tile, in 4 steps in the slow mode.
func (g *Game) movePlayer(dir uint8) {
	dx, dy := 0, 0
	switch dir {
	case dirL:
		dx = -1
	case dirR:
		dx = 1
	case dirU:
		dy = -1
	case dirD:
		dy = 1
	}
	x := g.posX * g.tileSize
	y := g.posY * g.tileSize
	tile := faceR + dir*4

	g.setPlayer(x, y, tile)
	g.DispUpdate()
	g.WaitMs(moveSpeed)

	if !g.fastMode {
		for k := uint8(1); k < 4; k++ {
			x += dx * (g.tileSize / 4)
			y += dy * (g.tileSize / 4)
			g.setPlayer(x, y, tile+k)
			g.DispUpdate()
			g.WaitMs(moveSpeed)
		}
	}

	g.posX += dx
	g.posY += dy
	g.setPlayer(g.posX*g.tileSize, g.posY*g.tileSize, tile)
	g.DispUpdate()
}

// clearBoard clears the board.
func (g *Game) clearBoard() {
	for i := range g.board {
		g.board[i] = tileEmpty
	}
}

// boardDim gets the current level and its dimension.
func (g *Game) boardDim() {
	g.levDef, g.levSolve = level(g.levels, g.level)
	g.levelW, g.levelH = 1, 0
	i := 0
	for k := 0; k < len(g.levDef); k++ {
		if ch := g.levDef[k]; ch == '!' || ch == '|' {
			g.levelH++
			if i > g.levelW {
				g.levelW = i
			}
			i = 0
		} else {
			i++
		}
	}
	if i > g.levelW {
		g.levelW = i
	}
	if i > 0 {
		g.levelH++
	}
}

// levelInit initializes the current level.
func (g *Game) levelInit() {
	g.boardDim()

	// the tile size
	ts := 32
	for g.levelW*ts > width || g.levelH*ts > height {
		ts -= 4
	}
	if ts < 4 {
		ts = 4
	}
	g.setTileMode(ts)
	g.levelX = (g.mapW - g.levelW) * g.tileSize / 2
	g.levelY = (g.mapH - g.levelH) * g.tileSize / 2

	g.clearBoard()

	// decode the level
	g.markNum = 0
	g.posX, g.posY = g.levelW/2, g.levelH/2
	x, y := 0, 0
	for k := 0; k < len(g.levDef); k++ {
		ch := g.levDef[k]
		if ch == '!' || ch == '|' {
			y++
			if y >= g.mapH {
				break
			}
			x = 0
			continue
		}
		if x >= g.mapW {
			continue
		}
		var t uint8
		switch ch {
		case 'x':
			t = tileEmpty
		case '#':
			t = tileWall
		case 'p', '@':
			g.posX, g.posY = x, y
			t = tileFloor
		case 'P', '+':
			g.posX, g.posY = x, y
			t = tileMark
			g.markNum++
		case 'b', '$':
			t = tileCrate
		case 'B', '*':
			t = tileFull
		case '.':
			t = tileMark
			g.markNum++
		default: // ' ', '_', '-'
			t = tileFloor
		}
		g.board[x+y*g.mapW] = t
		x++
	}

	g.dispBoard()
	g.setPlayer(g.posX*g.tileSize, g.posY*g.tileSize, faceD)
	g.DispUpdate()
	g.KeyFlush()
}

// isFloor: a floor, with or without a mark, no box.
func (g *Game) isFloor(x, y int) bool {
	t := g.getTile(x, y)
	return t == tileFloor || t == tileMark
}

// isBox: a box, with or without a mark.
func (g *Game) isBox(x, y int) bool {
	t := g.getTile(x, y)
	return t == tileCrate || t == tileFull
}

// hideBox takes the box away.
func (g *Game) hideBox(x, y int) {
	if g.getTile(x, y) == tileFull {
		g.markNum++
		g.putTile(x, y, tileMark)
	} else {
		g.putTile(x, y, tileFloor)
	}
}

// showBox puts a box.
func (g *Game) showBox(x, y int) {
	if g.getTile(x, y) == tileMark {
		g.markNum--
		g.putTile(x, y, tileFull)
	} else {
		g.putTile(x, y, tileCrate)
	}
}

// step moves the player (and pushes a box); it returns false on a key
// that is not a direction.
func (g *Game) step(key uint8) bool {
	dx, dy := 0, 0
	switch key {
	case picopad.KeyLeft:
		dx = -1
	case picopad.KeyRight:
		dx = 1
	case picopad.KeyUp:
		dy = -1
	case picopad.KeyDown:
		dy = 1
	}
	if dx+dy == 0 {
		return false
	}
	if g.isBox(g.posX+dx, g.posY+dy) && g.isFloor(g.posX+2*dx, g.posY+2*dy) {
		g.hideBox(g.posX+dx, g.posY+dy)
		g.showBox(g.posX+2*dx, g.posY+2*dy)
	}
	var dir uint8
	switch key {
	case picopad.KeyLeft:
		dir = dirL
	case picopad.KeyRight:
		dir = dirR
	case picopad.KeyUp:
		dir = dirU
	default:
		dir = dirD
	}
	if g.isFloor(g.posX+dx, g.posY+dy) {
		g.movePlayer(dir)
	}
	return true
}

// stepAnim does a step of a solution; it returns true on a key.
func (g *Game) stepAnim(key byte) bool {
	if key >= 'a' && key <= 'z' {
		key -= 32
	}
	switch key {
	case 'L':
		g.step(picopad.KeyLeft)
	case 'R':
		g.step(picopad.KeyRight)
	case 'U':
		g.step(picopad.KeyUp)
	case 'D':
		g.step(picopad.KeyDown)
	}
	return g.KeyGet() != picopad.NoKey
}

// at returns s[i], or 0 at the end (the C string end).
func at(s string, i int) byte {
	if i < len(s) {
		return s[i]
	}
	return 0
}

// subAnim plays the steps in brackets (s starts after the bracket); it
// returns true on a key.
func (g *Game) subAnim(s string) bool {
	for i := 0; i < len(s); i++ {
		ch := s[i]
		if ch == ')' {
			break
		}
		// a loop: the next step n-1 times here, the last time as usual
		if ch >= '0' && ch <= '9' {
			for n := ch - '0'; n > 1; n-- {
				if g.stepAnim(at(s, i+1)) {
					return true
				}
			}
			continue
		}
		if g.stepAnim(ch) {
			return true
		}
	}
	return false
}

// playSolve plays the solution of the level; it returns true on a key.
func (g *Game) playSolve() bool {
	g.levelInit()
	s := g.levSolve
	for i := 0; i < len(s); i++ {
		ch := s[i]
		if ch == '(' || ch == ')' {
			continue
		}
		// a loop (the last time as usual): steps or steps in brackets
		if ch >= '0' && ch <= '9' {
			n := int(ch - '0')
			if c := at(s, i+1); c >= '0' && c <= '9' {
				n = n*10 + int(c-'0')
				i++
			}
			for ; n > 1; n-- {
				if at(s, i+1) == '(' {
					if g.subAnim(s[i+2:]) {
						return true
					}
				} else if g.stepAnim(at(s, i+1)) {
					return true
				}
			}
			continue
		}
		if g.stepAnim(ch) {
			return true
		}
	}
	return false
}

// solvedAnim blinks the boxes of a solved level; it returns whether the
// level is solved.
func (g *Game) solvedAnim(sound bool) bool {
	if g.markNum > 0 {
		return false
	}
	// if (sound) PLAYSOUND(YippeeSnd)
	for i := 5; i > 0; i-- {
		for y := 0; y < g.mapH; y++ {
			for x := 0; x < g.mapW; x++ {
				if g.getTile(x, y) == tileFull {
					g.putTile(x, y, tileMark)
				}
			}
		}
		g.setPlayer(g.posX*g.tileSize, g.posY*g.tileSize, faceWin)
		g.DispUpdate()
		g.WaitMs(100)

		for y := 0; y < g.mapH; y++ {
			for x := 0; x < g.mapW; x++ {
				if g.getTile(x, y) == tileMark {
					g.putTile(x, y, tileFull)
				}
			}
		}
		g.setPlayer(g.posX*g.tileSize, g.posY*g.tileSize, faceD)
		g.DispUpdate()
		g.WaitMs(100)
	}
	return true
}

// levelInfo shows the author, the collection and the level.
func (g *Game) levelInfo() {
	g.setTileMode(0)
	g.SelFont8x16()
	g.DrawText(selAuthor, 0, fontH, picopad.ColWhite)
	g.DrawText(g.autName, 8*8, fontH, picopad.ColGreen)
	g.DrawText(selColl, 0, 2*fontH, picopad.ColWhite)
	g.DrawText(g.collName, 12*8, 2*fontH, picopad.ColGreen)
	g.DrawText("LEVEL:", 0, 3*fontH, picopad.ColWhite)
	g.DrawText(strconv.Itoa(g.level+1), 7*8, 3*fontH, picopad.ColGreen)
	g.DispUpdate()
}

// gameLoop plays the selected level until Y.
func (g *Game) gameLoop() {
	g.levelInit()
	for {
		i := g.KeyGet()

		// the slow mode: the held keys move, not the repeated ones
		if !g.fastMode {
			if i == picopad.NoKey {
				if g.KeyPressed(picopad.KeyLeft) {
					i = picopad.KeyLeft
				}
				if g.KeyPressed(picopad.KeyRight) {
					i = picopad.KeyRight
				}
				if g.KeyPressed(picopad.KeyUp) {
					i = picopad.KeyUp
				}
				if g.KeyPressed(picopad.KeyDown) {
					i = picopad.KeyDown
				}
			} else if !g.KeyPressed(picopad.KeyA) &&
				(i == picopad.KeyLeft || i == picopad.KeyRight || i == picopad.KeyUp || i == picopad.KeyDown) {
				i = picopad.NoKey
			}
		}
		if i == picopad.NoKey {
			continue
		}

		switch {
		case i == picopad.KeyY:
			return
		case i == picopad.KeyX: // the solution
			g.playSolve()
			g.solvedAnim(false)
			g.levelInit()
		case i == picopad.KeyB: // again
			g.levelInit()
		case i == picopad.KeyRight && g.KeyPressed(picopad.KeyA): // the next level
			g.level++
			if g.level >= g.levNum {
				g.level = 0
			}
			g.levelInfo()
			g.WaitMs(300)
			g.levelInit()
		case i == picopad.KeyLeft && g.KeyPressed(picopad.KeyA): // the previous level
			g.level--
			if g.level < 0 {
				g.level = g.levNum - 1
			}
			g.levelInfo()
			g.WaitMs(300)
			g.levelInit()
		case i == picopad.KeyUp && g.KeyPressed(picopad.KeyA):
			g.fastMode = true
		case i == picopad.KeyDown && g.KeyPressed(picopad.KeyA):
			g.fastMode = false
		default:
			g.KeyFlush()
			g.step(i)
		}

		// solved: the next level
		if g.solvedAnim(true) {
			g.DispUpdate()
			g.WaitMs(200)
			g.clearBoard()
			g.DispUpdate()
			g.WaitMs(100)
			g.level++
			if g.level >= g.levNum {
				g.level = 0
			}
			g.levelInfo()
			g.WaitMs(600)
			g.levelInit()
		}
	}
}

// selectAuthor sets the author i.
func (g *Game) selectAuthor(i int) {
	g.autInx = i
	g.autName = authors[i].name
	g.collect = authors[i].collect
	g.collNum = len(g.collect)
}

// selectColl sets the collection i.
func (g *Game) selectColl(i int) {
	g.collInx = i
	g.collName = g.collect[i].name
	g.levels = g.collect[i].levels
	g.levNum = g.collect[i].num
}

// Run plays until Y held in the demo (main of the C source, which then
// resets to the boot loader).
func (g *Game) Run() {
	g.setTileMode(0)
	g.DispUpdate()
	g.autInx = 0
	for {
		oldaut := g.autInx

		// the demo: the intro level and a random small one, until a key
		for {
			g.levNum, g.levels, g.level = 0, introLevel, 0
			if g.playSolve() {
				break
			}
			g.solvedAnim(false)

			for {
				g.selectAuthor(int(g.RandU8Max(uint8(len(authors) - 1))))
				g.selectColl(int(g.RandU8Max(uint8(g.collNum - 1))))
				g.level = int(g.RandU16Max(uint16(g.levNum - 1)))
				g.boardDim()
				if g.levelW <= 15 && g.levelH <= 12 {
					break
				}
			}
			if g.playSolve() {
				break
			}
			g.solvedAnim(false)
		}
		if g.KeyPressed(picopad.KeyY) {
			return
		}

		g.autInx = oldaut
		for g.authorSelect() {
			for g.collSelect() {
				for g.levSelect() {
					g.gameLoop()
				}
			}
		}
	}
}
